1	import {
2	  type PluginValue,
3	  ViewPlugin,
4	  type ViewUpdate,
5	  WidgetType,
6	  Decoration,
7	  type DecorationSet,
8	  EditorView,
9	} from "@codemirror/view";
10	import { parseLinktext, TFile, WorkspaceLeaf } from "obsidian";
11	import { VIEW_TYPE_TLDRAW_DG_PREVIEW } from "~/constants";
12	import type DiscourseGraphPlugin from "~/index";
13	import { extractLinktext, INTERNAL_LINK_RE } from "./internalLinkParsing";
14	
15	const buildObsidianUrl = (vaultName: string, filePath: string): string => {
16	  return `obsidian://open?vault=${encodeURIComponent(vaultName)}&file=${encodeURIComponent(filePath)}`;
17	};
18	
19	const resolveFileFromLinkText = (
20	  linkText: string,
21	  plugin: DiscourseGraphPlugin,
22	): TFile | null => {
23	  const activeFile = plugin.app.workspace.getActiveFile();
24	  if (!activeFile) return null;
25	
26	  // getFirstLinkpathDest takes a link path, so any #heading or #^block must go.
27	  const { path } = parseLinktext(linkText);
28	  if (!path) return null;
29	
30	  const resolved = plugin.app.metadataCache.getFirstLinkpathDest(
31	    path,
32	    activeFile.path,
33	  );
34	  return resolved instanceof TFile ? resolved : null;
35	};
36	
37	const setDragData = (
38	  e: DragEvent,
39	  file: TFile,
40	  plugin: DiscourseGraphPlugin,
41	): void => {
42	  const vaultName = plugin.app.vault.getName();
43	  const url = buildObsidianUrl(vaultName, file.path);
44	  e.dataTransfer?.setData("text/uri-list", url);
45	  e.dataTransfer?.setData("text/plain", url);
46	};
47	
48	// --- Live Preview ---
49	
50	/**
51	 * Widget that renders a small drag handle next to an internal link.
52	 * CM6 widgets get `ignoreEvent() → true` by default, which means
53	 * the editor completely ignores mouse events on them — native drag works.
54	 */
55	class WikilinkDragHandleWidget extends WidgetType {
56	  constructor(
57	    private linkPath: string,
58	    private plugin: DiscourseGraphPlugin,
59	  ) {
60	    super();
61	  }
62	
63	  eq(other: WikilinkDragHandleWidget): boolean {
64	    return this.linkPath === other.linkPath;
65	  }
66	
67	  toDOM(): HTMLElement {
68	    const handle = createSpan();
69	    handle.className =
70	      "inline-block cursor-grab opacity-30 hover:opacity-100 text-[10px] text-[var(--text-muted)] align-middle ml-0.5 transition-opacity duration-150 ease-in-out select-none";
71	    handle.draggable = true;
72	    handle.setAttribute("aria-label", "Drag to canvas");
73	    handle.textContent = "⠿";
74	
75	    handle.addEventListener("dragstart", (e) => {
76	      const file = resolveFileFromLinkText(this.linkPath, this.plugin);
77	      if (!file) {
78	        e.preventDefault();
79	        return;
80	      }
81	      setDragData(e, file, this.plugin);
82	    });
83	
84	    return handle;
85	  }
86	}
87	
88	const hasVisibleCanvasLeaf = (plugin: DiscourseGraphPlugin): boolean =>
89	  plugin.app.workspace
90	    .getLeavesOfType(VIEW_TYPE_TLDRAW_DG_PREVIEW)
91	    .some((leaf) =>
92	      (leaf as WorkspaceLeaf & { isVisible(): boolean }).isVisible(),
93	    );
94	const buildWidgetDecorations = (
95	  view: EditorView,
96	  plugin: DiscourseGraphPlugin,
97	): DecorationSet => {
98	  if (!hasVisibleCanvasLeaf(plugin)) return Decoration.none;
99	
100	  const widgets = [];
101	
102	  for (const { from, to } of view.visibleRanges) {
103	    const text = view.state.doc.sliceString(from, to);
104	    let match: RegExpExecArray | null;
105	    INTERNAL_LINK_RE.lastIndex = 0;
106	
107	    while ((match = INTERNAL_LINK_RE.exec(text)) !== null) {
108	      const checkPos = from + match.index - 1;
109	      const isEmbed =
110	        checkPos >= 0 &&
111	        view.state.doc.sliceString(checkPos, checkPos + 1) === "!";
112	      if (isEmbed) continue;
113	      const matchEnd = from + match.index + match[0].length;
114	      const linkPath = extractLinktext(match[0]);
115	      const widget = new WikilinkDragHandleWidget(linkPath, plugin);
116	      widgets.push(Decoration.widget({ widget, side: 1 }).range(matchEnd));
117	    }
118	  }
119	
120	  // Decorations must be sorted by position
121	  widgets.sort((a, b) => a.from - b.from);
122	  return Decoration.set(widgets);
123	};
124	
125	/**
126	 * CM6 ViewPlugin that adds a draggable grip icon after each internal link
127	 * in Live Preview. Matches both wikilinks (`[[...]]`) and markdown links
128	 * (`[text](path.md)`), inserting a widget decoration after each match.
129	 */
130	export const createWikilinkDragExtension = (
131	  plugin: DiscourseGraphPlugin,
132	): ViewPlugin<PluginValue> => {
133	  return ViewPlugin.fromClass(
134	    class {
135	      decorations: DecorationSet;
136	      private canvasVisible: boolean;
137	
138	      constructor(view: EditorView) {
139	        this.canvasVisible = hasVisibleCanvasLeaf(plugin);
140	        this.decorations = buildWidgetDecorations(view, plugin);
141	      }
142	
143	      update(update: ViewUpdate): void {
144	        const canvasVisible = hasVisibleCanvasLeaf(plugin);
145	        if (
146	          update.docChanged ||
147	          update.viewportChanged ||
148	          canvasVisible !== this.canvasVisible
149	        ) {
150	          this.canvasVisible = canvasVisible;
151	          this.decorations = buildWidgetDecorations(update.view, plugin);
152	        }
153	      }
154	    },
155	    {
156	      decorations: (v) => v.decorations,
157	    },
158	  );
159	};
