1	import { parseLinktext, type MarkdownPostProcessorContext } from "obsidian";
2	import type DiscourseGraphPlugin from "~/index";
3	import {
4	  badgeTargetPath,
5	  createDiscourseContextBadge,
6	  updateDiscourseContextBadge,
7	  DISCOURSE_CONTEXT_BADGE_CLASS,
8	} from "~/components/discourseContextBadge";
9	import { openDiscourseContextPopover } from "~/components/DiscourseContextPopover";
10	import { resolveDiscourseLinkTarget } from "./discourseLinkUtils";
11	
12	/**
13	 * A link inside a transclusion resolves against the embedded file, so walk the
14	 * `.internal-embed` chain outwards to find the file it was actually written in.
15	 */
16	const resolveLinkSourcePath = ({
17	  plugin,
18	  link,
19	  sourcePath,
20	}: {
21	  plugin: DiscourseGraphPlugin;
22	  link: HTMLElement;
23	  sourcePath: string;
24	}): string | null => {
25	  const embeds: HTMLElement[] = [];
26	  let embed = link.parentElement?.closest<HTMLElement>(".internal-embed");
27	  while (embed) {
28	    embeds.unshift(embed);
29	    embed = embed.parentElement?.closest<HTMLElement>(".internal-embed");
30	  }
31	
32	  let path = sourcePath;
33	  for (const ancestor of embeds) {
34	    const src = ancestor.getAttribute("src");
35	    if (!src) return null;
36	    const file = plugin.app.metadataCache.getFirstLinkpathDest(
37	      parseLinktext(src).path,
38	      path,
39	    );
40	    if (!file) return null;
41	    path = file.path;
42	  }
43	  return path;
44	};
