64	    if (!fileMetadata) {
65	      return <div>File metadata not available</div>;
66	    }
67	
68	    const frontmatter = fileMetadata.frontmatter;
69	    if (!frontmatter) {
70	      return <div>No discourse node data found</div>;
71	    }
72	
73	    if (!frontmatter.nodeTypeId) {
74	      return <div>Not a discourse node (no nodeTypeId)</div>;
75	    }
76	
77	    const nodeType = getNodeTypeById(plugin, frontmatter.nodeTypeId as string);
