89	      isImported && activeFile?.stat
90	        ? {
91	            createdAt: new Date(activeFile.stat.ctime).toLocaleString(),
92	            modifiedAt: new Date(modifiedAt).toLocaleString(),
93	          }
94	        : null;
95	
96	    const canPublish =
97	      plugin.settings.syncModeEnabled &&
98	      !isImported &&
99	      !!frontmatter.nodeTypeId;
100	
101	    const formattedVaultName = isImported
102	      ? getAndFormatImportSource(
103	          frontmatter.importedFromRid as string,
104	          plugin.settings.spaceNames,
105	        )
