134	            </button>
135	            {isImported && (
136	              <button
137	                onClick={() => {
138	                  void handleRefresh();
139	                }}
140	                disabled={isRefreshing}
141	                className="ml-auto rounded border px-2 py-1 text-xs"
142	                title="Refresh from source"
143	              >
144	                {isRefreshing ? "Refreshing..." : "🔄 Refresh"}
145	              </button>
146	            )}
147	            {canPublish && (
148	              <PublishGroupDropdown plugin={plugin} file={activeFile} />
