151	
152	          {isImported && (
153	            <div className="mt-3 flex items-center gap-1.5">
154	              <span className="cursor-default rounded bg-amber-300 px-2 py-1 text-xs font-semibold text-amber-950 dark:bg-amber-900/40 dark:text-amber-300">
155	                View only
156	              </span>
157	              <InfoTooltip
158	                content={
159	                  `Imported from ${formattedVaultName}. ` +
160	                  (frontmatter.authorId &&
