203	export class DiscourseContextView extends ItemView {
204	  private plugin: DiscourseGraphPlugin;
205	  private activeFile: TFile | null = null;
206	  private root: Root | null = null;
207	
208	  constructor(leaf: WorkspaceLeaf, plugin: DiscourseGraphPlugin) {
209	    super(leaf);
210	    this.plugin = plugin;
211	  }
212	
213	  setActiveFile(file: TFile | null): void {
214	    this.activeFile = file;
215	    this.updateView();
216	  }
217	
218	  getViewType(): string {
219	    return VIEW_TYPE_DISCOURSE_CONTEXT;
220	  }
221	
222	  getDisplayText(): string {
223	    return "Discourse context";
224	  }
225	
226	  getIcon(): string {
227	    return "telescope";
228	  }
229	
230	  // eslint-disable-next-line @typescript-eslint/require-await -- required by obsidian
231	  async onOpen(): Promise<void> {
232	    const container = this.containerEl.children[1];
233	    if (container) {
234	      container.empty();
235	      container.addClass("discourse-context-container");
236	
237	      this.root = createRoot(container);
238	
239	      this.activeFile = this.app.workspace.getActiveFile();
240	
241	      this.updateView();
242	
243	      this.registerEvent(
244	        this.app.workspace.on("file-open", (file) => {
245	          this.activeFile = file;
246	          this.updateView();
247	        }),
248	      );
249	    }
250	  }
251	
252	  updateView(): void {
253	    if (this.root) {
254	      this.root.render(
255	        <PluginProvider plugin={this.plugin}>
256	          <DiscourseContext activeFile={this.activeFile} />
257	        </PluginProvider>,
258	      );
259	    }
260	  }
261	
262	  // eslint-disable-next-line @typescript-eslint/require-await -- required by obsidian
263	  async onClose(): Promise<void> {
264	    if (this.root) {
265	      this.root.unmount();
266	      this.root = null;
267	    }
268	  }
269	}
